INSERT INTO subjects (id, code, name, description, created_at) VALUES
(1, 'INT3306', 'Phát triển Ứng dụng Web', 'Học phần cung cấp kiến thức toàn diện về kiến trúc Client-Server, HTML5/CSS3/TypeScript, React, RESTful API với Node.js/Express và bảo mật ứng dụng web.', '2026-09-01 09:00:00'),
(2, 'INT2208', 'Cơ sở Dữ liệu', 'Học phần trang bị kiến thức về mô hình dữ liệu quan hệ, đại số quan hệ, ngôn ngữ truy vấn SQL, chuẩn hóa lược đồ, chỉ mục và quản lý giao dịch (Transaction).', '2026-09-01 09:10:00'),
(3, 'INT2204', 'Lập trình Hướng đối tượng', 'Học phần trình bày 4 tính chất cốt lõi của OOP: Đóng gói, Kế thừa, Đa hình, Trừu tượng cùng các nguyên lý SOLID và Design Patterns cơ bản.', '2026-09-01 09:20:00'),
(4, 'INT2210', 'Cấu trúc Dữ liệu và Giải thuật', 'Nghiên cứu các cấu trúc dữ liệu mảng, danh sách liên kết, ngăn xếp, hàng đợi, cây nhị phân, bảng băm, đồ thị và phân tích độ phức tạp thuật toán.', '2026-09-01 09:30:00'),
(5, 'INT2213', 'Mạng Máy tính và Truyền thông', 'Kiến trúc mạng phân tầng OSI và TCP/IP, giao thức tầng ứng dụng (HTTP, DNS), tầng giao vận (TCP, UDP), định tuyến IP và bảo mật mạng.', '2026-09-01 09:40:00'),
(6, 'INT3108', 'Nhập môn Công nghệ Phần mềm', 'Quy trình phát triển phần mềm Agile/Scrum, phân tích đặc tả yêu cầu, thiết kế kiến trúc, kiểm thử phần mềm (Unit Test, Integration Test) và quản lý cấu hình Git.', '2026-09-01 09:50:00');

-- =========================================================================
-- 3. DỮ LIỆU ĐỀ THI (8 ĐỀ THI - MỖI ĐỀ TỪ 10 ĐẾN 15 CÂU HỎI)
-- =========================================================================

INSERT INTO exams (id, subject_id, created_by, title, description, duration_minutes, pass_score, is_published, created_at) VALUES
(1, 1, 2, 'Đề thi Giữa kỳ: Kiến trúc Web, React & RESTful API', 'Bài thi đánh giá kiến thức về giao thức HTTP, React Hooks, định tuyến phân quyền, TypeScript và kết nối RESTful API.', 25, 5.00, TRUE, '2026-10-01 08:00:00'),
(2, 1, 2, 'Đề thi Cuối kỳ: Bảo mật Web, Xác thực JWT & Tối ưu Hiệu năng', 'Đánh giá chuyên sâu về cơ chế xác thực JWT, phân quyền RBAC, phòng chống XSS/SQLi/CSRF, CORS và tối ưu hóa ứng dụng React.', 20, 5.00, TRUE, '2026-10-10 09:00:00'),
(3, 2, 3, 'Đề thi Cuối kỳ: Hệ Quản trị Cơ sở Dữ liệu & Truy vấn SQL', 'Kiểm tra kỹ năng thiết kế lược đồ quan hệ, ràng buộc khóa ngoại, truy vấn JOIN, GROUP BY, Subquery và chuẩn hóa dữ liệu.', 25, 5.00, TRUE, '2026-10-05 10:00:00'),
(4, 3, 2, 'Đề thi Giữa kỳ: Nguyên lý Lập trình Hướng đối tượng (OOP)', 'Bài thi kiểm tra kiến thức về Lớp, Đối tượng, Đóng gói, Kế thừa, Đa hình, Trừu tượng, Interface và nguyên lý thiết kế SOLID.', 20, 6.00, TRUE, '2026-10-08 14:00:00'),
(5, 4, 4, 'Đề thi Giữa kỳ: Cấu trúc Dữ liệu & Phân tích Giải thuật', 'Đánh giá kiến thức về độ phức tạp Big-O, Ngăn xếp (Stack), Hàng đợi (Queue), Cây nhị phân tìm kiếm (BST), Bảng băm và thuật toán sắp xếp.', 25, 5.00, TRUE, '2026-10-12 08:30:00'),
(6, 5, 5, 'Đề thi Cuối kỳ: Kiến trúc Mạng OSI, TCP/IP và Giao thức', 'Đánh giá kiến thức về mô hình 7 tầng OSI, bộ giao thức TCP/IP, địa chỉ IPv4/Subnetting, DNS, HTTP/HTTPS và định tuyến mạng.', 20, 5.00, TRUE, '2026-10-15 13:30:00'),
(7, 6, 4, 'Bài kiểm tra: Quy trình Phần mềm Agile/Scrum & Kiểm thử', 'Kiểm tra kiến thức về vòng đời phần mềm SDLC, mô hình Scrum, User Story, quản lý mã nguồn Git và các cấp độ kiểm thử phần mềm.', 15, 5.00, TRUE, '2026-10-18 15:00:00'),
(8, 2, 3, 'Đề thi Chuyên đề: Tối ưu Chỉ mục (Index) & Giao dịch (ACID)', 'Đề thi nâng cao về cấu trúc B+ Tree Index, tính chất ACID của Transaction, mức cô lập (Isolation Levels) và xử lý Deadlock.', 20, 6.00, FALSE, '2026-10-20 16:00:00');

